/**
 * Import everything into the CMS:
 *   1. every dhātu generated by Vidyut (data/generated/dhatus.json)
 *   2. the curated conversational layer (data/curated/verbs.json): English meanings, featured set, overrides
 *   3. nouns & pronouns, situations, phrases and the default practice deck
 *   4. a first admin user
 *
 *   npm run seed            (safe to re-run: refreshes Vidyut forms, never overwrites editors' meanings,
 *                            overrides or review status)
 */
import fs from 'node:fs'
import path from 'node:path'
import { getPayload, type Where } from 'payload'
import { sql } from '@payloadcms/db-postgres'
import config from '../src/payload.config'

const root = process.cwd()
const read = (p: string) => JSON.parse(fs.readFileSync(path.join(root, p), 'utf-8'))

async function main() {
  const payload = await getPayload({ config })
  const ctx = { context: { skipRevalidate: true }, depth: 0 } as const
  const log = (...a: unknown[]) => console.log('·', ...a)

  // ── admin user ──────────────────────────────────────────────────────────
  const email = process.env.SEED_ADMIN_EMAIL, password = process.env.SEED_ADMIN_PASSWORD
  if (email && password) {
    const u = await payload.find({ collection: 'users', where: { email: { equals: email } }, limit: 1 })
    if (!u.docs.length) { await payload.create({ collection: 'users', data: { email, password, name: 'Admin', roles: ['admin', 'reviewer'] } }); log('admin user', email) }
  }

  // ── dhātus ──────────────────────────────────────────────────────────────
  const gen = read('data/generated/dhatus.json')
  // everyday verbs (featured) + common prefixed verbs (listed in the "With prefixes" tab)
  const prefixedFile = path.join(root, 'data/curated/prefixed.json')
  const curated: any[] = [
    ...read('data/curated/verbs.json').map((c: any) => ({ ...c, _set: 'featured' })),
    ...(fs.existsSync(prefixedFile) ? read('data/curated/prefixed.json') : []).map((c: any) => ({ ...c, _set: 'prefixed' })),
  ]
  const curBySlug = new Map(curated.map((c) => [c.code + (c.prefixes?.length ? '-' + c.prefixes.join('-') : ''), c]))
  const glossFile = path.join(root, 'data/generated/glosses.json')
  const glosses: Record<string, { gloss: string; short: string }> = fs.existsSync(glossFile) ? JSON.parse(fs.readFileSync(glossFile, 'utf-8')) : {}
  const shortMeaning = (g?: { gloss: string }) => (g ? g.gloss.split(';')[0].split(',').slice(0, 3).join(',').trim() : undefined)
  const existing = new Map<string, number>()
  const hasMeanings = new Set<string>()
  for (let page = 1; ; page++) {
    const r = await payload.find({ collection: 'dhatus', limit: 1000, page, depth: 0, select: { slug: true, meaning_te: true } as any })
    r.docs.forEach((d: any) => { existing.set(d.slug, d.id as number); if (d.meaning_te) hasMeanings.add(d.slug) })
    if (!r.hasNextPage) break
  }
  let created = 0, updated = 0
  const t0 = Date.now()
  for (const d of gen.dhatus) {
    const c = curBySlug.get(d.slug)
    const display = c?.display || (d.prefixes?.length ? `${c?.prefixesDev?.join(' + ') || d.prefixes.join(' + ')} + ${d.root}` : d.root)
    const data: Record<string, unknown> = {
      root: d.root, display, slug: d.slug, code: d.code, aupadeshika: d.aupadeshika, gana: d.gana, artha_sa: d.artha_sa,
      prefixes: d.prefixes || [], padas: d.padas, forms: d.forms, participle: d.participle, derived: d.derived || null,
      generatedWith: `vidyut ${gen.vidyut} · ${gen.generated}`,
      gloss: glosses[d.slug]?.gloss,
      meaning_en: shortMeaning(glosses[d.slug]),
    }
    const meanings = c?.meanings ? { meaning_te: c.meanings.te, meaning_kn: c.meanings.kn, meaning_ta: c.meanings.ta } : {}
    if (c) Object.assign(data, meanings, {
      meaning_en: c.meaning_en, featured: c._set === 'featured', commonPrefixed: c._set === 'prefixed' || !!c.prefixes?.length,
      irregular: !!c.irregular, order: c.order, preferredPada: c.preferredPada,
      overrides: (c.overrides || []).map((o: any) => ({ scope: o.scope, form: o.stem || o.form, label: o.label, note: o.note, showFirst: true, lakara: o.lakara, pada: o.pada, index: o.index })),
      status: 'checked',
    })
    const id = existing.get(d.slug)
    if (id) {
      // Re-runs only refresh what Vidyut owns; meanings, overrides and review status stay as editors left them.
      const generated: any = { root: data.root, code: data.code, aupadeshika: data.aupadeshika, gana: data.gana, artha_sa: data.artha_sa, padas: data.padas, forms: data.forms, participle: data.participle, derived: data.derived, generatedWith: data.generatedWith }
      // meanings in Telugu / Kannada / Tamil: filled once from the curated files, then editors own them
      if (c?.meanings && !hasMeanings.has(d.slug)) Object.assign(generated, meanings)
      if (c) generated.commonPrefixed = c._set === 'prefixed' || !!c.prefixes?.length
      await payload.update({ collection: 'dhatus', id, data: generated, ...ctx }); updated++
    }
    else { const doc = await payload.create({ collection: 'dhatus', data: data as any, ...ctx }); existing.set(d.slug, doc.id as number); created++ }
    if ((created + updated) % 250 === 0) log(`${created + updated} / ${gen.dhatus.length} dhatus…`)
  }
  log(`dhatus: ${created} created, ${updated} updated in ${((Date.now() - t0) / 1000).toFixed(0)}s`)
  // Every seed update writes a version of each dhātu; keep only the latest generated one so the free database stays small.
  await (payload.db as any).drizzle.execute(sql`DELETE FROM "_dhatus_v" v USING (SELECT parent_id, MAX(id) AS keep FROM "_dhatus_v" GROUP BY parent_id) k WHERE v.parent_id = k.parent_id AND v.id <> k.keep`)
  log('old dhātu versions pruned')

  // ── nouns ───────────────────────────────────────────────────────────────
  for (const n of read('data/generated/nouns.json')) {
    const where: Where = { and: [{ stemSlp1: { equals: n.stemSlp1 } }, { gender: { equals: n.gender } }] }
    const f = await payload.find({ collection: 'nouns', where, limit: 1 })
    const data = { display: n.display, stemSlp1: n.stemSlp1, gender: n.gender, kind: n.kind || 'noun', meaning_en: n.meaning_en, forms: n.forms, gloss: n.note }
    f.docs.length ? await payload.update({ collection: 'nouns', id: f.docs[0].id, data, ...ctx }) : await payload.create({ collection: 'nouns', data, ...ctx })
  }
  log('nouns & pronouns imported')

  // ── situations & phrases ────────────────────────────────────────────────
  const phraseIds = new Map<string, number>()
  for (const s of read('data/curated/phrases.json')) {
    const f = await payload.find({ collection: 'situations', where: { title: { equals: s.title } }, limit: 1 })
    const sit = f.docs[0] ? await payload.update({ collection: 'situations', id: f.docs[0].id, data: { title: s.title, titleSa: s.titleSa, order: s.order }, ...ctx })
      : await payload.create({ collection: 'situations', data: { title: s.title, titleSa: s.titleSa, order: s.order }, ...ctx })
    for (const p of s.phrases) {
      const dhatu = existing.get(p.dhatu)
      if (!dhatu) { console.warn('missing dhatu', p.dhatu); continue }
      const data = { label: p.label, situation: sit.id, dhatu, order: p.order, words: p.words.map((text: string) => ({ text })), english: p.english }
      const ex = await payload.find({ collection: 'phrases', where: { label: { equals: p.label } }, limit: 1 })
      const doc = ex.docs[0] ? await payload.update({ collection: 'phrases', id: ex.docs[0].id, data, ...ctx }) : await payload.create({ collection: 'phrases', data, ...ctx })
      phraseIds.set(p.label, (doc as { id: number }).id)
    }
  }
  log(`${phraseIds.size} phrases imported`)

  // ── practice deck ───────────────────────────────────────────────────────
  const deck = read('data/curated/practice.json')
  const cards = deck.cards.filter((c: any) => phraseIds.has(c.phrase)).map((c: any) => ({ ...c, phrase: phraseIds.get(c.phrase) }))
  const dk = await payload.find({ collection: 'practice-decks', where: { title: { equals: deck.title } }, limit: 1 })
  const ddata = { title: deck.title, isDefault: true, cards }
  dk.docs[0] ? await payload.update({ collection: 'practice-decks', id: dk.docs[0].id, data: ddata, ...ctx }) : await payload.create({ collection: 'practice-decks', data: ddata, ...ctx })
  log(`practice deck "${deck.title}" with ${cards.length} cards`)

  // ── Ambuda examples (if generated) ──────────────────────────────────────
  const exFile = path.join(root, 'data/generated/examples.json')
  if (fs.existsSync(exFile)) {
    let n = 0
    for (const e of JSON.parse(fs.readFileSync(exFile, 'utf-8'))) {
      const dhatu = existing.get(e.dhatu)
      if (!dhatu) continue
      const f = await payload.find({ collection: 'examples', where: { and: [{ source: { equals: e.source } }, { dhatu: { equals: dhatu } }] }, limit: 1 })
      const data = { text: e.text, dhatu, form: e.form, token: e.token, source: e.source, url: e.url, translation: e.translation, licence: e.licence }
      f.docs[0] ? await payload.update({ collection: 'examples', id: f.docs[0].id, data, ...ctx }) : await payload.create({ collection: 'examples', data, ...ctx })
      n++
    }
    log(`${n} Ambuda examples imported`)
  }
  log('done ✓')
  process.exit(0)
}

main().catch((e) => { console.error(e); process.exit(1) })
